#!/usr/bin/env python3
"""Embed the finished PNG sprites into a JS file as data URIs.

Android WebView can fail to load image files from file:///android_asset/.
Data URIs avoid that path completely while keeping the same artwork.
"""
from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parents[1]
ASSETS = ROOT / "assets"
OUT = ROOT / "js" / "sprites-data.js"

sprites = {
    "charlie": "charlie-unicorn.png",
    "buddyBlue": "buddy-blue.png",
    "buddyPink": "buddy-pink.png",
}

lines = [
    "// Generated by scripts/embed-sprites.py. Do not edit by hand.",
    "const SPRITE_DATA = {",
]
for key, filename in sprites.items():
    raw = (ASSETS / filename).read_bytes()
    uri = "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
    lines.append("  %s: '%s'," % (key, uri))
lines.extend([
    "};",
    "",
    "if (typeof window !== 'undefined') window.SPRITE_DATA = SPRITE_DATA;",
    "if (typeof globalThis !== 'undefined') globalThis.SPRITE_DATA = SPRITE_DATA;",
    "",
])
OUT.write_text("\n".join(lines))
print("wrote", OUT, OUT.stat().st_size, "bytes")
